interface MqttEntity {
    entity: 'triggered' | 'lastImage' | 'lastClassname' | 'lastZones' | 'lastLabel' | string;
    domain: 'sensor' | 'binary_sensor' | 'image' | 'switch' | 'button' | 'select' | 'alarm_control_panel';
    name: string;
    className?: string,
    key?: string,
    deviceClass?: string,
    icon?: string;
    entityCategory?: 'diagnostic' | 'config';
    valueToDispatch?: any;
    forceDiscoveryId?: string;
    forceInfoId?: string;
    forceStateId?: string;
    forceCommandId?: string;
    unitOfMeasurement?: string;
    disabled?: boolean;
    stateClass?: string;
    precision?: number;
    options?: string[];
    retain?: boolean;
    identifier?: MqttEntityIdentifier;
    supportedFeatures?: string[];
    /** If true, do not publish empty payload to command_topic during discovery (avoids triggering our own subscription and HA sync) */
    skipCommandTopicReset?: boolean;
}

/** MQTT entities for accessory switches, derived from accessoryUtils. */
const cameraAccessorySwitchEntities: Record<CameraAccessorySwitchKind, MqttEntity> = (
    Object.entries(cameraAccessorySwitchEntityConfig) as [CameraAccessorySwitchKind, typeof cameraAccessorySwitchEntityConfig[CameraAccessorySwitchKind]][]
).reduce((acc, [kind, config]) => {
    acc[kind] = {
        domain: 'switch',
        entity: config.entity,
        name: config.name,
        icon: config.icon,
        retain: false,
        options: [],
    };
    return acc;
}, {} as Record<CameraAccessorySwitchKind, MqttEntity>);

const getCameraAccessorySwitchEntities = (kinds?: CameraAccessorySwitchKind[]) => {
    if (!kinds?.length) {
        return [] as MqttEntity[];
    }
    const uniqKinds = uniq(kinds);
    return uniqKinds.map((kind) => cameraAccessorySwitchEntities[kind]).filter(Boolean);
}

