const getBasicMqttAutodiscoveryConfiguration = (props: {
    mqttEntity: MqttEntity,
    mqttDevice: AutodiscoveryConfig['dev'],
    deviceId: string,
    additionalProps?: Partial<AutodiscoveryConfig>,
    stateTopic: string,
    commandTopic?: string,
    infoTopic?: string,
}) => {
    const { mqttEntity, mqttDevice, deviceId, additionalProps = {}, stateTopic, commandTopic, infoTopic } = props;
    const { entity, domain, name, icon, deviceClass,
        entityCategory, options, unitOfMeasurement,
        stateClass, precision, disabled, supportedFeatures = []
    } = mqttEntity;

    const config: AutodiscoveryConfig = {
        dev: mqttDevice,
        unique_id: `${idPrefix}-${deviceId}-${toKebabCase(entity)}`,
        default_entity_id: `${domain}.${toSnakeCase(`${mqttDevice.name} ${name}`.trim())}`,
        name,
        platform: domain,
        optimistic: false,
        retain: false,
        qos: 0,
        device_class: deviceClass,
        state_class: stateClass,
        icon,
        entity_category: entityCategory,
        unit_of_measurement: unitOfMeasurement,
        suggested_display_precision: precision,
        json_attributes_topic: infoTopic,
        options,
        ...additionalProps
    };

    if (disabled) {
        config.enabled_by_default = false;
    }

    if (domain === 'binary_sensor') {
        config.payload_on = PAYLOAD_ON;
        config.payload_off = PAYLOAD_OFF;
        config.state_topic = stateTopic;
    } else if (domain === 'image') {
        config.image_topic = stateTopic;
        config.image_encoding = 'b64';
        // config.url_topic = stateTopic;
    } else if (domain === 'sensor') {
        config.state_topic = stateTopic;
    } else if (domain === 'switch') {
        config.state_topic = stateTopic;
        config.command_topic = commandTopic;
        config.payload_on = PAYLOAD_ON;
        config.payload_off = PAYLOAD_OFF;
    } else if (domain === 'button') {
        config.command_topic = commandTopic;
        config.payload_press = PAYLOAD_PRESS;
    } else if (domain === 'select') {
        config.command_topic = commandTopic;
        config.state_topic = stateTopic;
    } else if (domain === 'alarm_control_panel') {
        config.command_topic = commandTopic;
        config.state_topic = stateTopic;
        config.supported_features = supportedFeatures;
        config.code_arm_required = false;
        config.code_disarm_required = false;
        config.code_trigger_required = false;
        // Home Assistant MQTT Alarm Control Panel expects these command payload defaults.
        // See: https://www.home-assistant.io/integrations/alarm_control_panel.mqtt/
        config.payload_arm_away = HA_ALARM_PAYLOAD_ARM_AWAY;
        config.payload_arm_night = HA_ALARM_PAYLOAD_ARM_NIGHT;
        config.payload_arm_home = HA_ALARM_PAYLOAD_ARM_HOME;
        config.payload_disarm = HA_ALARM_PAYLOAD_DISARM;
        config.payload_trigger = HA_ALARM_PAYLOAD_TRIGGER;
    }

    return config;
}

export const getMqttAutodiscoveryConfiguration = async (props: {
    mqttEntity: MqttEntity,
    additionalProps?: Partial<AutodiscoveryConfig>,
    device: MqttDeviceType
}) => {
    const { mqttEntity, additionalProps = {}, device } = props;

    const { mqttDevice, deviceId } = await getMqttDevice(device);

    const { commandTopic, discoveryTopic, stateTopic, infoTopic } = getMqttTopics({ mqttEntity, device });

    const config = getBasicMqttAutodiscoveryConfiguration({
        deviceId,
        mqttDevice,
        mqttEntity,
        stateTopic,
        commandTopic,
        additionalProps,
        infoTopic,
    });

    return { discoveryTopic, config, stateTopic, commandTopic };
}

const lastDetectionSuffix = '_last_detection';
const lastImageSuffix = '_last_image';

const getDetectionClassMqttEntities = (classes: string[]) => classes.flatMap(className => {
    const parsedClassName = toTitleCase(className);
    const isAudio = isAudioClassname(className);
    const entries: MqttEntity[] = [
        {
            entity: `${className}_detected`,
            name: `${parsedClassName} detected`,
            domain: 'binary_sensor',
            className,
            valueToDispatch: PAYLOAD_OFF,
            deviceClass: isAudio ? 'sound' : 'motion',
            identifier: MqttEntityIdentifier.Detected
        },
        {
            entity: `${className}${lastImageSuffix}`,
            name: `${parsedClassName} last image`,
            domain: 'image',
            className,
            retain: true,
            identifier: MqttEntityIdentifier.LastImage
        },
        {
            entity: `${className}${lastDetectionSuffix}`,
            name: `${parsedClassName} last detection`,
            domain: 'sensor',
            className,
            icon: 'mdi:clock',
            deviceClass: 'timestamp',
            retain: true,
            disabled: true,
            identifier: MqttEntityIdentifier.LastDetection
        },
    ];

    if (!isAudio && isLabelDetection(className)) {
        entries.push({
            entity: `${className}_last_recognized`,
            name: `${parsedClassName} last recognized`,
            domain: 'sensor',
            className,
            identifier: MqttEntityIdentifier.LastLabel
        });
    }

    if (detectionClassForObjectsReporting.includes(className as DetectionClass)) {
        entries.push({
            entity: `${className}_objects`,
            name: `${parsedClassName} objects`,
            domain: 'sensor',
            icon: detectionClassMdiIconMap[className],
            className,
            identifier: MqttEntityIdentifier.Object
        });
    }

    return entries;
});

export const getRuleMqttEntities = (props: {
    rule: BaseRule,
    device?: ScryptedDeviceBase,
    forDiscovery: boolean
}): MqttEntity[] => {
    const { rule, device, forDiscovery } = props;
    const { name } = rule;
    const entity = toSnakeCase(name);
    const parsedName = toTitleCase(name);
    const isPluginRuleForDevice = rule.source === RuleSource.Plugin && !!device;
    const isPluginRuleForPlugin = rule.source === RuleSource.Plugin && !device;
    const isDeviceRuleForDevice = rule.source === RuleSource.Device && !!device;
    const isOwnRule = isPluginRuleForPlugin || isDeviceRuleForDevice

    const switchEntity: MqttEntity = {
        entity: `${entity}_active`,
        name: `${parsedName} active`,
        domain: 'switch',
        entityCategory: 'config',
        retain: false,
        identifier: MqttEntityIdentifier.RuleActive
    };
    const runningEntity: MqttEntity = {
        entity: `${entity}_running`,
        name: `${parsedName} running`,
        domain: 'binary_sensor',
        deviceClass: 'running',
        entityCategory: 'diagnostic',
        identifier: MqttEntityIdentifier.RuleRunning
    };
    const triggeredEntity: MqttEntity = {
        entity: `${entity}_triggered`,
        name: `${parsedName} triggered`,
        domain: 'binary_sensor',
        deviceClass: rule.ruleType === RuleType.Audio ? 'sound' : rule.ruleType === RuleType.Detection ? 'motion' : undefined,
        identifier: MqttEntityIdentifier.Triggered
    };
    const occupiedEntity: MqttEntity = {
        entity: `${entity}_occupied`,
        name: `${parsedName} occupied`,
        domain: 'binary_sensor',
        deviceClass: 'occupancy',
        retain: true,
        identifier: MqttEntityIdentifier.Occupied
    };
    const lastImageEntity: MqttEntity = {
        entity: `${entity}${lastImageSuffix}`,
        name: `${parsedName} last image`,
        domain: 'image',
        retain: true,
        identifier: MqttEntityIdentifier.LastImage
    };
    const lastTriggerEntity: MqttEntity = {
        entity: `${entity}${lastDetectionSuffix}`,
        name: `${parsedName} last triggered`,
        domain: 'sensor',
        icon: 'mdi:clock',
        deviceClass: 'timestamp',
        retain: true,
        disabled: true,
        identifier: MqttEntityIdentifier.LastTrigger
    };

    const entities: MqttEntity[] = [
        {
            ...runningEntity,
            disabled: isOwnRule,
            forceStateId: isPluginRuleForDevice ? pluginId : undefined,
        },
    ];

    if (isOwnRule) {
        entities.push(switchEntity);
    }

    if (isDetectionRule(rule)) {
        if (isOwnRule) {
            entities.push(
                triggeredEntity,
                lastImageEntity,
                lastTriggerEntity,
            );
        }

        if (isPluginRuleForDevice) {
            entities.push(
                lastImageEntity,
                triggeredEntity,
                lastTriggerEntity,
            );

            if (!forDiscovery) {
                entities.push(
                    { ...triggeredEntity, forceStateId: pluginId },
                    { ...lastImageEntity, forceStateId: pluginId },
                    { ...lastTriggerEntity, forceStateId: pluginId },
                );
            }
        }

    } else if (rule.ruleType === RuleType.Occupancy && isDeviceRuleForDevice) {
        entities.push(
            occupiedEntity,
            lastImageEntity,
            lastTriggerEntity,
        );
    }

    return entities;
}

const getPersonMqttEntities = (person: string) => {
    const personId = toSnakeCase(person);
    const personName = toTitleCase(person);

    const personEntity: MqttEntity = {
        entity: `${personId}`,
        name: `${personName}`,
        domain: 'sensor',
        icon: 'mdi:account',
        retain: true,
        identifier: MqttEntityIdentifier.PersonRoom
    };
    const lastImageEntity: MqttEntity = {
        entity: `${personId}${lastImageSuffix}`,
        name: `${personName} last image`,
        domain: 'image',
        retain: true,
        identifier: MqttEntityIdentifier.LastImage
    };
    const lastTriggerEntity: MqttEntity = {
        entity: `${personId}${lastDetectionSuffix}`,
        name: `${personName} last triggered`,
        domain: 'sensor',
        icon: 'mdi:clock',
        deviceClass: 'timestamp',
        retain: true,
        disabled: true,
        identifier: MqttEntityIdentifier.LastTrigger
    };

    return [personEntity, lastImageEntity, lastTriggerEntity];
};

export const getMqttTopics = (props: {
    mqttEntity: MqttEntity,
    device: MqttDeviceType
}) => {
    const { mqttEntity, device } = props;
    const deviceIdParent = typeof device === 'string' ? device : device?.id;
    const { entity, domain, forceStateId, forceCommandId, forceDiscoveryId, forceInfoId } = mqttEntity;
    const stateTopic = `${idPrefix}/${idPrefix}-${forceStateId ?? deviceIdParent}/${entity}`;
    const commandTopic = `${idPrefix}/${idPrefix}-${forceCommandId ?? deviceIdParent}/${entity}/set`;
    const infoTopic = `${idPrefix}/${idPrefix}-${forceInfoId ?? deviceIdParent}/${entity}/info`;
    const discoveryTopic = `homeassistant/${domain}/${idPrefix}-${forceDiscoveryId ?? deviceIdParent}/${entity}/config`;

    return {
        stateTopic,
        commandTopic,
        infoTopic,
        discoveryTopic
    };
}

const toDeviceDiscoveryComponentId = (mqttEntity: MqttEntity) => {
    const raw = `${mqttEntity.domain}-${mqttEntity.entity}`;
    const kebab = toKebabCase(raw);
    return kebab.replace(/[^a-zA-Z0-9_-]/g, '_');
}

/**
 * Build device-based discovery payload: one message per device with all components in "cmps".
 * See https://www.home-assistant.io/integrations/mqtt/#device-discovery-payload
 */
const buildDeviceDiscoveryPayload = (props: {
    mqttDevice: AutodiscoveryConfig['dev'],
    deviceId: string,
    mqttEntities: MqttEntity[],
    device: MqttDeviceType,
    streamDestinations?: ScryptedStreamDestination[],
}) => {
    const { mqttDevice, deviceId, mqttEntities, device, streamDestinations } = props;
    const cmps: Record<string, Record<string, unknown>> = {};

    for (const mqttEntity of mqttEntities) {
        const { commandTopic, stateTopic, infoTopic } = getMqttTopics({ mqttEntity, device });
        const fullConfig = getBasicMqttAutodiscoveryConfiguration({
            deviceId,
            mqttDevice,
            mqttEntity,
            stateTopic,
            commandTopic,
            infoTopic,
        });
        const { dev: _dev, ...componentConfig } = fullConfig;
        cmps[toDeviceDiscoveryComponentId(mqttEntity)] = componentConfig as Record<string, unknown>;
    }

    // Add camera components for each stream destination (WS-transport: platform field guides HA integration)
    if (streamDestinations?.length) {
        for (const dest of streamDestinations) {
            const key = `camera_${dest.name.toLowerCase().replace(/\s+/g, '_')}`;
            const displayName = dest.destination
                ? `${dest.name} (${dest.destination})`
                : dest.name;
            cmps[key] = {
                platform: 'camera',
                name: displayName,
                rtsp_url: dest.rtspUrl,
                still_image_url: dest.snapshotUrl,
            };
        }
    }

    return {
        dev: mqttDevice,
        o: { name: namePrefix, url: 'https://github.com/apocaliss92/scrypted-advanced-notifier' },
        cmps,
    };
};

/**
 * Publish MQTT discovery: device-based only (one message per device with all components in "cmps").
 * Clears any old single-component topics for this device so HA does not see conflicting discovery.
 */
export const publishMqttDeviceDiscovery = async (props: {
    mqttClient?: IHaClient,
    mqttEntities: MqttEntity[],
    device: MqttDeviceType,
    console: Console,
    /** Initial entity states to publish right after discovery (e.g. for switches with retain so HA shows correct state) */
    initialEntityStates?: Record<string, string>,
    /** Stream destinations to expose as camera entities (WS transport only) */
    streamDestinations?: ScryptedStreamDestination[],
}) => {
    const { mqttClient, mqttEntities, device, console, initialEntityStates, streamDestinations } = props;

    if (!mqttClient) {
        return;
    }

    const deviceIdParent = typeof device === 'string' ? device : device?.id;
    const { mqttDevice, deviceId } = await getMqttDevice(device);

    const devicePayload = buildDeviceDiscoveryPayload({ mqttDevice, deviceId, mqttEntities, device, streamDestinations });
    await mqttClient.publish(getDeviceDiscoveryTopic(device), JSON.stringify(devicePayload), true);
    console.log(`Device ${idPrefix}-${deviceIdParent}: discovered ${mqttEntities.length} entities`);

    const statePublishes: Array<{ topic: string; payload: string; retain?: boolean }> = [];
    const entitiesEnsuredReset: string[] = [];
    for (const mqttEntity of mqttEntities) {
        if (mqttEntity.valueToDispatch !== undefined) {
            const { stateTopic } = getMqttTopics({ mqttEntity, device });
            statePublishes.push({ topic: stateTopic, payload: mqttEntity.valueToDispatch, retain: mqttEntity.retain });
        }
        if (['switch', 'button'].includes(mqttEntity.domain) && !mqttEntity.skipCommandTopicReset) {
            const { commandTopic } = getMqttTopics({ mqttEntity, device });
            entitiesEnsuredReset.push(commandTopic);
        }
    }
    for (const { topic, payload, retain } of statePublishes) {
        await mqttClient.publish(topic, payload, retain);
    }
    for (const commandTopic of entitiesEnsuredReset) {
        await mqttClient.publish(commandTopic, '', true);
    }

    // Publish initial entity states (e.g. for switches) right after discovery so HA shows correct state
    if (initialEntityStates) {
        console.info(`[publishMqttDeviceDiscovery] Publishing ${Object.keys(initialEntityStates).length} initial entity states: ${JSON.stringify(initialEntityStates)}`);
        for (const [entityName, value] of Object.entries(initialEntityStates)) {
            const entity = mqttEntities.find(e => e.entity === entityName);
            if (entity) {
                const { stateTopic } = getMqttTopics({ mqttEntity: entity, device });
                await mqttClient.publish(stateTopic, value, true);
            } else {
                console.info(`[publishMqttDeviceDiscovery] Entity "${entityName}" not found in mqttEntities, skipping initial state`);
            }
        }
    } else {
        console.info(`[publishMqttDeviceDiscovery] No initialEntityStates provided`);
    }

    // Log entities with valueToDispatch that were published
    const dispatchedEntities = mqttEntities.filter(e => e.valueToDispatch !== undefined).map(e => ({ entity: e.entity, value: e.valueToDispatch }));
    if (dispatchedEntities.length) {
        console.info(`[publishMqttDeviceDiscovery] Entities with valueToDispatch: ${JSON.stringify(dispatchedEntities)}`);
    }

    return [getDeviceDiscoveryTopic(device)];
}

const getDeviceDiscoveryTopic = (device: MqttDeviceType) => {
    const deviceIdParent = typeof device === 'string' ? device : device?.id;
    return `homeassistant/device/${idPrefix}-${deviceIdParent}/config`;
}

const clearRetainedTopic = async (mqttClient: IHaClient, topic: string) => {
    await mqttClient.publish(topic, '', true);
}

const clearTopicsForEntities = async (props: {
    mqttClient: IHaClient,
    device: MqttDeviceType,
    mqttEntities: MqttEntity[],
}) => {
    const { mqttClient, device, mqttEntities } = props;

    await clearRetainedTopic(mqttClient, getDeviceDiscoveryTopic(device));
    for (const mqttEntity of mqttEntities) {
        const { stateTopic, commandTopic, infoTopic } = getMqttTopics({ mqttEntity, device });
        await clearRetainedTopic(mqttClient, stateTopic);
        await clearRetainedTopic(mqttClient, commandTopic);
        await clearRetainedTopic(mqttClient, infoTopic);
    }
}

export const resetAllPluginMqttTopicsAndRediscover = async (props: {
    mqttClient?: IHaClient,
    console: Console,
    rules: BaseRule[],
    people: string[],
    cameras?: Array<{ device: ScryptedDeviceBase & ObjectDetector, rules: BaseRule[], zones: string[], occupancyEnabled: boolean }>,
    sensors?: Array<{ device: ScryptedDeviceBase, rules: BaseRule[] }>,
    notifiers?: Array<{ device: ScryptedDeviceBase & Notifier }>,
    alarmSupportedModes?: SecuritySystemMode[],
}) => {
    const {
        mqttClient,
        console,
        rules,
        people,
        cameras = [],
        sensors = [],
        notifiers = [],
        alarmSupportedModes,
    } = props;

    if (!mqttClient) {
        return;
    }

    // Build plugin entities (same semantics as setupPluginAutodiscovery).
    const pluginEntities: MqttEntity[] = [];
    for (const rule of rules) {
        const ruleEntities = getRuleMqttEntities({ rule, forDiscovery: true });
        for (const mqttEntity of ruleEntities) {
            let entityToPublish = mqttEntity;
            if (mqttEntity.identifier === MqttEntityIdentifier.RuleActive) {
                entityToPublish = { ...mqttEntity, valueToDispatch: rule.isEnabled };
            } else if (mqttEntity.identifier === MqttEntityIdentifier.RuleRunning) {
                entityToPublish = { ...mqttEntity, valueToDispatch: rule.currentlyActive };
            } else if (mqttEntity.identifier === MqttEntityIdentifier.Triggered
                || mqttEntity.identifier === MqttEntityIdentifier.Occupied) {
                entityToPublish = { ...mqttEntity, valueToDispatch: mqttEntity.valueToDispatch ?? PAYLOAD_OFF };
            }
            pluginEntities.push(entityToPublish);
        }
    }

    const peopleEntities: MqttEntity[] = [];
    for (const person of people) {
        peopleEntities.push(...getPersonMqttEntities(person));
    }

    const {
        notificationsEnabledEntity,
        rpcObjectsEntity,
        rssMemoryEntity,
        heapMemoryEntity,
        pendingResultsEntity,
    } = getBasicMqttEntities();

    pluginEntities.push(
        notificationsEnabledEntity,
        rpcObjectsEntity,
        rssMemoryEntity,
        heapMemoryEntity,
        pendingResultsEntity,
    );

    console.log('Resetting all plugin MQTT retained topics and rediscovering');
    await clearTopicsForEntities({ mqttClient, device: pluginId, mqttEntities: pluginEntities });
    await clearTopicsForEntities({ mqttClient, device: peopleTrackerId, mqttEntities: peopleEntities });

    if (alarmSupportedModes) {
        const {
            alarmSystemEntity,
        } = getBasicMqttEntities();

        const alarmEntities: MqttEntity[] = [{
            ...alarmSystemEntity,
            supportedFeatures: alarmSupportedModes.map(mode => AlarmSupportedFeatureToHaMap[mode]),
        }];

        await clearTopicsForEntities({ mqttClient, device: alarmSystemId, mqttEntities: alarmEntities });
    }

    for (const camera of cameras) {
        const detectionMqttEntities = (await getCameraClassEntities({ device: camera.device, console })).filter(entity => {
            if (entity.identifier === MqttEntityIdentifier.Object && !camera.occupancyEnabled) {
                return false;
            }
            return true;
        });

        const {
            audioPressureEntity,
            batteryEntity,
            chargerEntity,
            notificationsEnabledEntity,
            onlineEntity,
            ptzPresetEntity,
            rebootEntity,
            recordingEntity,
            snapshotsEntity,
            rebroadcastEntity,
            sleepingEntity,
            triggeredEntity,
        } = getBasicMqttEntities();

        const mqttEntities: MqttEntity[] = [
            triggeredEntity,
            notificationsEnabledEntity,
            rebroadcastEntity,
            snapshotsEntity,
            ...detectionMqttEntities,
        ];

        if (camera.device.interfaces.includes(ScryptedInterface.Battery)) {
            mqttEntities.push(cloneDeep(batteryEntity));
        }
        if (camera.device.interfaces.includes(ScryptedInterface.Charger)) {
            mqttEntities.push(cloneDeep(chargerEntity));
        }
        if (camera.device.interfaces.includes(ScryptedInterface.Online)) {
            mqttEntities.push(cloneDeep(onlineEntity));
        }
        if (camera.device.interfaces.includes(ScryptedInterface.Sleep)) {
            mqttEntities.push(cloneDeep(sleepingEntity));
        }
        if (camera.device.interfaces.includes(ScryptedInterface.VideoRecorder)) {
            mqttEntities.push(recordingEntity);
        }
        if (camera.device.interfaces.includes(ScryptedInterface.Reboot)) {
            mqttEntities.push(rebootEntity);
        }
        if (camera.device.interfaces.includes(ScryptedInterface.AudioVolumeControl)) {
            mqttEntities.push(audioPressureEntity);
        }
        if (camera.device.interfaces.includes(ScryptedInterface.PanTiltZoom)) {
            const presets = Object.values(camera.device.ptzCapabilities.presets ?? {});
            if (presets?.length) {
                mqttEntities.push({ ...ptzPresetEntity, options: presets });
            }
            mqttEntities.push(...getPtzCommandEntities(camera.device));
        }

        for (const rule of camera.rules) {
            const ruleEntities = getRuleMqttEntities({ rule, device: camera.device, forDiscovery: true });
            for (const mqttEntity of ruleEntities) {
                if (mqttEntity.identifier === MqttEntityIdentifier.RuleActive) {
                    mqttEntities.push({ ...mqttEntity, valueToDispatch: rule.isEnabled });
                } else if (mqttEntity.identifier === MqttEntityIdentifier.RuleRunning) {
                    mqttEntities.push({ ...mqttEntity, valueToDispatch: rule.currentlyActive });
                } else {
                    mqttEntities.push(mqttEntity);
                }
            }
        }

        mqttEntities.push(...getDetectionZoneEntities(camera.zones));
        await clearTopicsForEntities({ mqttClient, device: camera.device, mqttEntities });
    }

    for (const sensor of sensors) {
        const mqttEntities: MqttEntity[] = [];
        for (const rule of sensor.rules) {
            const ruleEntities = getRuleMqttEntities({ rule, device: sensor.device, forDiscovery: true });
            for (const mqttEntity of ruleEntities) {
                if (mqttEntity.identifier === MqttEntityIdentifier.RuleActive) {
                    mqttEntities.push({ ...mqttEntity, valueToDispatch: rule.isEnabled });
                } else if (mqttEntity.identifier === MqttEntityIdentifier.RuleRunning) {
                    mqttEntities.push({ ...mqttEntity, valueToDispatch: rule.currentlyActive });
                } else {
                    mqttEntities.push(mqttEntity);
                }
            }
        }
        await clearTopicsForEntities({ mqttClient, device: sensor.device, mqttEntities });
    }

    for (const notifier of notifiers) {
        const { notificationsEnabledEntity } = getBasicMqttEntities();
        await clearTopicsForEntities({
            mqttClient,
            device: notifier.device,
            mqttEntities: [notificationsEnabledEntity],
        });
    }

    await setupPluginAutodiscovery({ mqttClient, people, console, rules });
    if (alarmSupportedModes) {
        await setupAlarmSystemAutodiscovery({ mqttClient, console, supportedModes: alarmSupportedModes });
    }
    for (const camera of cameras) {
        await setupCameraAutodiscovery({
            mqttClient,
            device: camera.device,
            console,
            rules: camera.rules,
            zones: camera.zones,
        });
    }
    for (const sensor of sensors) {
        await setupSensorAutodiscovery({ mqttClient, device: sensor.device, rules: sensor.rules, console });
    }
    for (const notifier of notifiers) {
        await setupNotifierAutodiscovery({ mqttClient, device: notifier.device, console });
    }
}

export const setupPluginAutodiscovery = async (props: {
    mqttClient?: IHaClient,
    people: string[],
    console: Console,
    rules: BaseRule[];
    hasNvrStoragePaths?: boolean;
}) => {
    const { people, mqttClient, rules, console, hasNvrStoragePaths } = props;

    if (!mqttClient) {
        return;
    }

    const mqttEntities: MqttEntity[] = [];

    for (const rule of rules) {
        const ruleEntities = getRuleMqttEntities({ rule, forDiscovery: true });

        for (const mqttEntity of ruleEntities) {
            let entityToPublish = mqttEntity;
            if (mqttEntity.identifier === MqttEntityIdentifier.RuleActive) {
                entityToPublish = {
                    ...mqttEntity,
                    valueToDispatch: rule.isEnabled,
                };
            } else if (mqttEntity.identifier === MqttEntityIdentifier.RuleRunning) {
                entityToPublish = {
                    ...mqttEntity,
                    valueToDispatch: rule.currentlyActive
                };
            } else if (mqttEntity.identifier === MqttEntityIdentifier.Triggered
                || mqttEntity.identifier === MqttEntityIdentifier.Occupied) {
                entityToPublish = {
                    ...mqttEntity,
                    valueToDispatch: mqttEntity.valueToDispatch ?? PAYLOAD_OFF,
                };
            }

            mqttEntities.push(entityToPublish);
        }
    }

    const peopleEntities: MqttEntity[] = [];
    for (const person of people) {
        const personEntities = getPersonMqttEntities(person);
        peopleEntities.push(...personEntities);
    }

    const {
        notificationsEnabledEntity,
        rpcObjectsEntity,
        rssMemoryEntity,
        heapMemoryEntity,
        pendingResultsEntity,
        nvrStorageHealthEntity,
    } = getBasicMqttEntities();

    mqttEntities.push(
        notificationsEnabledEntity,
        rpcObjectsEntity,
        rssMemoryEntity,
        heapMemoryEntity,
        pendingResultsEntity,
    );

    if (hasNvrStoragePaths) {
        mqttEntities.push(nvrStorageHealthEntity);
    }

    const pluginTopics = await publishMqttDeviceDiscovery({ mqttClient, mqttEntities, console, device: pluginId });
    const peopleTopics = await publishMqttDeviceDiscovery({ mqttClient, mqttEntities: peopleEntities, device: peopleTrackerId, console });

    return [
        ...(pluginTopics ?? []),
        ...(peopleTopics ?? []),
    ];
}

export const setupAlarmSystemAutodiscovery = async (props: {
    mqttClient?: IHaClient,
    console: Console,
    supportedModes: SecuritySystemMode[],
}) => {
    const { mqttClient, console, supportedModes } = props;

    if (!mqttClient) {
        return;
    }

    const mqttEntities: MqttEntity[] = [];

    const {
        alarmSystemEntity,
    } = getBasicMqttEntities();

    mqttEntities.push({
        ...alarmSystemEntity,
        supportedFeatures: uniq([
            ...supportedModes.map(mode => AlarmSupportedFeatureToHaMap[mode]).filter(Boolean) as string[],
            'trigger',
        ]),
    });

    return await publishMqttDeviceDiscovery({ mqttClient, mqttEntities, device: alarmSystemId, console });
}

export const subscribeToPluginMqttTopics = async (
    props: {
        mqttClient?: IHaClient,
        entitiesActiveTopic?: string,
        rules: BaseRule[],
        activeEntitiesCb: (activeEntities: string[]) => void,
        switchNotificationsEnabledCb: (active: boolean) => void,
        console: Console,
        activationRuleCb: (props: {
            ruleName: string;
            active: boolean
        }) => void,
        /** Previously subscribed topics — unsubscribed before re-subscribing to prevent callback accumulation. */
        previousTopics?: string[],
    }
): Promise<string[]> => {
    const {
        activeEntitiesCb,
        entitiesActiveTopic,
        mqttClient,
        rules,
        activationRuleCb,
        switchNotificationsEnabledCb,
        previousTopics,
    } = props;

    if (!mqttClient) {
        return [];
    }

    if (previousTopics?.length) {
        try { await mqttClient.unsubscribe(previousTopics); } catch { /* ignore */ }
    }

    const subscribedTopics: string[] = [];

    if (entitiesActiveTopic) {
        mqttClient.subscribe([entitiesActiveTopic], async (messageTopic, message) => {
            const messageString = message.toString();
            if (messageTopic === entitiesActiveTopic) {
                activeEntitiesCb(messageString !== 'null' ? JSON.parse(messageString) : [])
            }
        });
        subscribedTopics.push(entitiesActiveTopic);
    }

    const { notificationsEnabledEntity } = getBasicMqttEntities();

    if (switchNotificationsEnabledCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: notificationsEnabledEntity, device: pluginId });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                if (message === PAYLOAD_ON) {
                    switchNotificationsEnabledCb(true);
                } else if (message === PAYLOAD_OFF) {
                    switchNotificationsEnabledCb(false);
                }

                await mqttClient.publish(stateTopic, message, notificationsEnabledEntity.retain);
            }
        });
        subscribedTopics.push(commandTopic, stateTopic);
    }

    for (const rule of rules) {
        const ruleActiveEntity = getRuleMqttEntities({ rule, forDiscovery: false }).find(item => item.identifier === MqttEntityIdentifier.RuleActive);
        if (ruleActiveEntity) {
            const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: ruleActiveEntity, device: pluginId });
            await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
                if (messageTopic === commandTopic) {
                    if (message === PAYLOAD_ON) {
                        activationRuleCb({
                            active: true,
                            ruleName: rule.name,
                        });
                    } else if (message === PAYLOAD_OFF) {
                        activationRuleCb({
                            active: false,
                            ruleName: rule.name,
                        });
                    }

                    await mqttClient.publish(stateTopic, message, ruleActiveEntity.retain);
                }
            });
            subscribedTopics.push(commandTopic, stateTopic);
        }
    }

    return subscribedTopics;
}

export const subscribeToAlarmSystemMqttTopics = async (
    props: {
        mqttClient?: IHaClient,
        modeSwitchCb: (mode: SecuritySystemMode) => void,
        triggerCb?: () => void,
        console: Console,
    }
) => {
    const {
        mqttClient,
        modeSwitchCb,
        triggerCb,
    } = props;

    if (!mqttClient) {
        return;
    }

    const { alarmSystemEntity } = getBasicMqttEntities();

    if (modeSwitchCb || triggerCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: alarmSystemEntity, device: alarmSystemId });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                // HA sends command payloads (ARM_*, DISARM, TRIGGER by default).
                // Map them to Scrypted SecuritySystemMode.
                if (message === HA_ALARM_PAYLOAD_DISARM || message === SecuritySystemMode.Disarmed) {
                    modeSwitchCb(SecuritySystemMode.Disarmed);
                    return;
                }
                if (message === HA_ALARM_PAYLOAD_ARM_AWAY || message === SecuritySystemMode.AwayArmed) {
                    modeSwitchCb(SecuritySystemMode.AwayArmed);
                    return;
                }
                if (message === HA_ALARM_PAYLOAD_ARM_HOME || message === SecuritySystemMode.HomeArmed) {
                    modeSwitchCb(SecuritySystemMode.HomeArmed);
                    return;
                }
                if (message === HA_ALARM_PAYLOAD_ARM_NIGHT || message === SecuritySystemMode.NightArmed) {
                    modeSwitchCb(SecuritySystemMode.NightArmed);
                    return;
                }
                if (message === HA_ALARM_PAYLOAD_TRIGGER) {
                    triggerCb?.();
                    return;
                }
            }
        });
    }
}

const getPtzCommandEntities = (device: ScryptedDeviceBase) => {
    const {
        ptzDownEntity,
        ptzLeftEntity,
        ptzRightEntity,
        ptzUpEntity,
        ptzZoomInEntity,
        ptzZoomOutEntity,
    } = getBasicMqttEntities();

    const commandEntities: MqttEntity[] = [];

    if (device.ptzCapabilities?.zoom) {
        commandEntities.push(ptzZoomInEntity, ptzZoomOutEntity)
    }
    if (device.ptzCapabilities?.pan) {
        commandEntities.push(ptzLeftEntity, ptzRightEntity)
    }
    if (device.ptzCapabilities?.tilt) {
        commandEntities.push(ptzUpEntity, ptzDownEntity)
    }

    return commandEntities;
}

export const subscribeToCameraMqttTopics = async (
    props: {
        mqttClient?: IHaClient,
        rules: BaseRule[],
        device: ScryptedDeviceBase,
        console: Console,
        switchRecordingCb?: (active: boolean) => void,
        switchSnapshotsCb?: (active: boolean) => void,
        switchRebroadcastCb?: (active: boolean) => void,
        switchNotificationsEnabledCb: (active: boolean) => void,
        rebootCb?: () => void,
        ptzCommandCb?: (command: PanTiltZoomCommand) => void,
        accessorySwitchKinds?: CameraAccessorySwitchKind[],
        accessorySwitchCb?: (props: { kind: CameraAccessorySwitchKind; active: boolean }) => Promise<void> | void,
        activationRuleCb: (props: {
            ruleName: string;
            active: boolean;
            ruleType: RuleType;
        }) => void,
        /** Previously subscribed topics — unsubscribed before re-subscribing to prevent callback accumulation. */
        previousTopics?: string[],
    }
): Promise<string[]> => {
    const {
        mqttClient,
        rules,
        activationRuleCb,
        switchRecordingCb,
        switchSnapshotsCb,
        switchRebroadcastCb,
        switchNotificationsEnabledCb,
        rebootCb,
        ptzCommandCb,
        accessorySwitchKinds,
        accessorySwitchCb,
        device,
        previousTopics,
    } = props;
    if (!mqttClient) {
        return [];
    }

    if (previousTopics?.length) {
        try { await mqttClient.unsubscribe(previousTopics); } catch { /* ignore */ }
    }

    const subscribedTopics: string[] = [];

    for (const rule of rules) {
        const mqttEntity = getRuleMqttEntities({ rule, device, forDiscovery: false })?.find(item => item.identifier === MqttEntityIdentifier.RuleActive);

        if (mqttEntity) {
            const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity, device });

            await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
                if (messageTopic === commandTopic) {
                    if (message === PAYLOAD_ON) {
                        activationRuleCb({
                            active: true,
                            ruleName: rule.name,
                            ruleType: rule.ruleType
                        });
                    } else if (message === PAYLOAD_OFF) {
                        activationRuleCb({
                            active: false,
                            ruleName: rule.name,
                            ruleType: rule.ruleType
                        });
                    }

                    await mqttClient.publish(stateTopic, message, mqttEntity.retain);
                }
            });
            subscribedTopics.push(commandTopic, stateTopic);
        }
    }

    const {
        notificationsEnabledEntity,
        privacyEntity,
        ptzDownEntity,
        ptzLeftEntity,
        ptzPresetEntity,
        ptzRightEntity,
        ptzUpEntity,
        ptzZoomInEntity,
        ptzZoomOutEntity,
        rebootEntity,
        recordingEntity,
        snapshotsEntity,
        rebroadcastEntity,
    } = getBasicMqttEntities();

    if (switchRebroadcastCb && switchSnapshotsCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: privacyEntity, device });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                const privacyOn = message === PAYLOAD_ON;
                const enable = !privacyOn;
                await Promise.all([
                    Promise.resolve(switchRebroadcastCb(enable)),
                    Promise.resolve(switchSnapshotsCb(enable)),
                    switchRecordingCb ? Promise.resolve(switchRecordingCb(enable)) : Promise.resolve(),
                ]);
                await mqttClient.publish(stateTopic, message, privacyEntity.retain);
            }
        });
        subscribedTopics.push(commandTopic, stateTopic);
    }

    if (switchRecordingCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: recordingEntity, device });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                if (message === PAYLOAD_ON) {
                    switchRecordingCb(true);
                } else if (message === PAYLOAD_OFF) {
                    switchRecordingCb(false);
                }

                await mqttClient.publish(stateTopic, message, recordingEntity.retain);
            }
        });
        subscribedTopics.push(commandTopic, stateTopic);
    }

    if (switchSnapshotsCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: snapshotsEntity, device });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                if (message === PAYLOAD_ON) {
                    switchSnapshotsCb(true);
                } else if (message === PAYLOAD_OFF) {
                    switchSnapshotsCb(false);
                }

                await mqttClient.publish(stateTopic, message, snapshotsEntity.retain);
            }
        });
        subscribedTopics.push(commandTopic, stateTopic);
    }

    if (switchRebroadcastCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: rebroadcastEntity, device });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                if (message === PAYLOAD_ON) {
                    switchRebroadcastCb(true);
                } else if (message === PAYLOAD_OFF) {
                    switchRebroadcastCb(false);
                }

                await mqttClient.publish(stateTopic, message, rebroadcastEntity.retain);
            }
        });
        subscribedTopics.push(commandTopic, stateTopic);
    }

    if (switchNotificationsEnabledCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: notificationsEnabledEntity, device });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                if (message === PAYLOAD_ON) {
                    switchNotificationsEnabledCb(true);
                } else if (message === PAYLOAD_OFF) {
                    switchNotificationsEnabledCb(false);
                }

                await mqttClient.publish(stateTopic, message, notificationsEnabledEntity.retain);
            }
        });
        subscribedTopics.push(commandTopic, stateTopic);
    }

    if (accessorySwitchKinds?.length && accessorySwitchCb) {
        const accessoryEntities = getCameraAccessorySwitchEntities(accessorySwitchKinds);
        const kindByEntity = new Map<string, CameraAccessorySwitchKind>([
            [cameraAccessorySwitchEntities.siren_on_motion.entity, 'siren_on_motion'],
            [cameraAccessorySwitchEntities.siren.entity, 'siren'],
            [cameraAccessorySwitchEntities.light_on_motion.entity, 'light_on_motion'],
            [cameraAccessorySwitchEntities.light.entity, 'light'],
            [cameraAccessorySwitchEntities.pir.entity, 'pir'],
            [cameraAccessorySwitchEntities.autotracking.entity, 'autotracking'],
        ]);

        for (const mqttEntity of accessoryEntities) {
            const kind = kindByEntity.get(mqttEntity.entity);
            if (!kind) {
                continue;
            }
            const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity, device });
            await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
                if (messageTopic === commandTopic) {
                    if (message === PAYLOAD_ON) {
                        await accessorySwitchCb({ kind, active: true });
                        await mqttClient.publish(stateTopic, PAYLOAD_ON, mqttEntity.retain);
                    } else if (message === PAYLOAD_OFF) {
                        await accessorySwitchCb({ kind, active: false });
                        await mqttClient.publish(stateTopic, PAYLOAD_OFF, mqttEntity.retain);
                    }
                }
            });
            subscribedTopics.push(commandTopic, stateTopic);
        }
    }

    if (rebootCb) {
        const { commandTopic } = getMqttTopics({ mqttEntity: rebootEntity, device });
        await mqttClient.subscribe([commandTopic], async (messageTopic) => {
            if (messageTopic === commandTopic) {
                if (messageTopic === PAYLOAD_PRESS) {
                    rebootCb();

                    await mqttClient.publish(commandTopic, '', true);
                }
            }
        });
        subscribedTopics.push(commandTopic);
    }

    if (ptzCommandCb) {
        const commandEntities = getPtzCommandEntities(device);
        commandEntities.push(ptzPresetEntity);

        for (const commandEntity of commandEntities) {
            const { stateTopic, commandTopic } = getMqttTopics({ mqttEntity: commandEntity, device });

            await mqttClient.subscribe([commandTopic], async (messageTopic, message) => {
                if (messageTopic === commandTopic) {
                    if (commandEntity.entity === ptzPresetEntity.entity) {
                        ptzCommandCb({ preset: message });

                        await mqttClient.publish(stateTopic, 'None');
                    } else if (message === PAYLOAD_PRESS) {
                        if (commandEntity.entity === ptzZoomInEntity.entity) {
                            ptzCommandCb({ zoom: 0.1 });
                        } else if (commandEntity.entity === ptzZoomOutEntity.entity) {
                            ptzCommandCb({ zoom: -0.1 });
                        } else if (commandEntity.entity === ptzRightEntity.entity) {
                            ptzCommandCb({ pan: 0.1 });
                        } else if (commandEntity.entity === ptzLeftEntity.entity) {
                            ptzCommandCb({ pan: -0.1 });
                        } else if (commandEntity.entity === ptzDownEntity.entity) {
                            ptzCommandCb({ tilt: -0.1 });
                        } else if (commandEntity.entity === ptzUpEntity.entity) {
                            ptzCommandCb({ tilt: 0.1 });
                        }

                        await mqttClient.publish(commandTopic, '', true);
                    }
                }
            });
            subscribedTopics.push(commandTopic);
        }
    }

    return subscribedTopics;
}

export const subscribeToNotifierMqttTopics = async (
    props: {
        mqttClient?: IHaClient,
        device: ScryptedDeviceBase,
        console: Console,
        switchNotificationsEnabledCb: (active: boolean) => void,
        snoozeCb: (props: { snoozeId: string, snoozeTime: number, cameraId: string }) => void,
    }
) => {
    const {
        mqttClient,
        device,
        switchNotificationsEnabledCb,
        snoozeCb,
        console,
    } = props;

    if (!mqttClient) {
        return;
    }

    const {
        notificationsEnabledEntity,
        snoozeEntity,
    } = getBasicMqttEntities();

    if (switchNotificationsEnabledCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: notificationsEnabledEntity, device });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                if (message === PAYLOAD_ON) {
                    switchNotificationsEnabledCb(true);
                } else if (message === PAYLOAD_OFF) {
                    switchNotificationsEnabledCb(false);
                }

                await mqttClient.publish(stateTopic, message, notificationsEnabledEntity.retain);
            }
        });
    }

    if (snoozeCb) {
        const { commandTopic, stateTopic } = getMqttTopics({ mqttEntity: snoozeEntity, device });
        await mqttClient.subscribe([commandTopic, stateTopic], async (messageTopic, message) => {
            if (messageTopic === commandTopic) {
                const payload = safeParseJson(message);
                try {
                    const { snoozeId, snoozeTime, cameraId } = payload;

                    if (cameraId && snoozeId && snoozeTime) {
                        snoozeCb({ cameraId, snoozeId, snoozeTime: Number(snoozeTime) });
                        await mqttClient.publish(commandTopic, '', true);
                    }
                } catch (e) {
                    console.error(`Error processing snooze command: ${message} ${commandTopic} ${stateTopic} ${snoozeEntity}`, e);
                }
            }
        });
    }
}

