const getMqttDevice = async (device: MqttDeviceType) => {
    let deviceId: string;
    let mqttDevice: AutodiscoveryConfig['dev'];

    if (typeof device === 'object') {
        deviceId = device.id;
        const localEndpoint = await sdk.endpointManager.getLocalEndpoint();
        const deviceConfigurationUrl = `${new URL(localEndpoint).origin}/endpoint/@scrypted/core/public/#/device/${deviceId}`;
        const deviceName = (device.name != null && String(device.name).trim() !== '')
            ? String(device.name).trim()
            : (device.id || 'Camera');
        mqttDevice = {
            ids: [`${idPrefix}-${device.id}`],
            name: deviceName,
            manufacturer: namePrefix,
            model: `${device?.info?.manufacturer ?? ''} ${device?.info?.model ?? ''}`.trim(),
            via_device: pluginIds,
            configuration_url: deviceConfigurationUrl
        }
    } else {
        if (device === peopleTrackerId) {
            deviceId = peopleTrackerId;
            mqttDevice = {
                ids: [`${idPrefix}-${peopleTrackerId}`],
                name: `${namePrefix} people tracker`,
                manufacturer: namePrefix,
                via_device: pluginIds,
            }
        } else if (device === pluginId) {
            deviceId = pluginId;
            mqttDevice = {
                ids: [pluginIds],
                name: `${namePrefix} plugin settings`,
                manufacturer: namePrefix,
            }
        } else if (device === alarmSystemId) {
            deviceId = alarmSystemId;
            mqttDevice = {
                ids: [`${idPrefix}-${alarmSystemId}`],
                name: `${namePrefix} alarm system`,
                manufacturer: namePrefix,
                via_device: pluginIds,
            }
        }
    }

    return {
        mqttDevice,
        deviceId,
    }
}

const getCameraClassEntities = async (props: {
    device: ScryptedDeviceBase & ObjectDetector,
    console: Console,
}) => {
    const { console, device } = props;
    const enabledClasses: string[] = [];
    if (device.interfaces.includes(ScryptedInterface.MotionSensor)) {
        enabledClasses.push(DetectionClass.Motion);
    }

    if (device.type === ScryptedDeviceType.Doorbell) {
        enabledClasses.push(DetectionClass.Doorbell);
    }

    if (device.interfaces.includes(ScryptedInterface.ObjectDetector)) {
        try {
            const objectTypes = await device.getObjectTypes();
            const detectionClassesSet = new Set<string>();

            for (const supportedClass of objectTypes.classes) {
                const defaultClass = detectionClassesDefaultMap[supportedClass];
                if (defaultClass || isAudioClassname(supportedClass)) {
                    detectionClassesSet.add(supportedClass);
                } else {
                    console.info(`Class ${supportedClass} not supported`);
                }
            }

            enabledClasses.push(
                ...Array.from(detectionClassesSet),
                DetectionClass.AnyObject,
            );
        } catch { }
    }

    return getDetectionClassMqttEntities(uniq(enabledClasses));
}

const getDetectionZoneEntities = (zones: string[]) => {
    const entries: MqttEntity[] = []

    for (const zone of zones) {
        const entityZoneName = toSnakeCase(zone);

        for (const className of detectionClassForObjectsReporting) {
            const friendlyClassName = toTitleCase(className);
            entries.push(
                {
                    entity: `${entityZoneName}_${className}_detected`,
                    name: `${zone} - ${friendlyClassName} detected`,
                    domain: 'binary_sensor',
                    className,
                    valueToDispatch: PAYLOAD_OFF,
                    deviceClass: 'motion',
                    identifier: MqttEntityIdentifier.Detected
                },
                {
                    entity: `${entityZoneName}_${className}${lastImageSuffix}`,
                    name: `${zone} - ${friendlyClassName} last image`,
                    domain: 'image',
                    className,
                    retain: true,
                    identifier: MqttEntityIdentifier.LastImage
                },
                {
                    entity: `${entityZoneName}_${className}${lastDetectionSuffix}`,
                    name: `${zone} - ${friendlyClassName} last detection`,
                    domain: 'sensor',
                    className,
                    icon: 'mdi:clock',
                    deviceClass: 'timestamp',
                    retain: true,
                    disabled: true,
                    identifier: MqttEntityIdentifier.LastDetection
                },
                {
                    entity: `${entityZoneName}_${className}_objects`,
                    name: `${zone} - ${friendlyClassName} objects`,
                    domain: 'sensor',
                    className,
                    icon: detectionClassMdiIconMap[className],
                    identifier: MqttEntityIdentifier.Object
                }
            );
        }
    }

    return entries;
}

/** Builds the MQTT entity list for a camera (same as setupCameraAutodiscovery). Used for clear + rediscover. */
export const getCameraMqttEntitiesForDiscovery = async (props: {
    device: ScryptedDeviceBase & ObjectDetector,
    console: Console,
    rules: BaseRule[],
    zones: string[],
    accessorySwitchKinds?: CameraAccessorySwitchKind[],
}): Promise<MqttEntity[]> => {
    const { device, rules, console, zones, accessorySwitchKinds } = props;
    const detectionMqttEntities = await getCameraClassEntities({ device, console });
    const {
        audioPressureEntity,
        batteryEntity,
        chargerEntity,
        notificationsEnabledEntity,
        onlineEntity,
        ptzPresetEntity,
        privacyEntity,
        rebootEntity,
        recordingEntity,
        snapshotsEntity,
        rebroadcastEntity,
        sleepingEntity,
        triggeredEntity,
    } = getBasicMqttEntities();

    const mqttEntities: MqttEntity[] = [
        triggeredEntity,
        notificationsEnabledEntity,
        { ...rebroadcastEntity, skipCommandTopicReset: true },
        { ...snapshotsEntity, skipCommandTopicReset: true },
        { ...privacyEntity, skipCommandTopicReset: true },
        ...detectionMqttEntities
    ];

    mqttEntities.push(...getCameraAccessorySwitchEntities(accessorySwitchKinds));

    const hasBattery = device.interfaces.includes(ScryptedInterface.Battery);
    const hasCharger = device.interfaces.includes(ScryptedInterface.Charger);
    const hasOnline = device.interfaces.includes(ScryptedInterface.Online);
    const hasSleep = device.interfaces.includes(ScryptedInterface.Sleep);
    console.info(`[getCameraMqttEntitiesForDiscovery] Device "${device.name}" (${device.id}) diagnostic interfaces: Battery=${hasBattery}, Charger=${hasCharger}, Online=${hasOnline}, Sleep=${hasSleep}`);
    console.info(`[getCameraMqttEntitiesForDiscovery] Device interfaces: ${JSON.stringify(device.interfaces)}`);

    if (hasBattery) {
        mqttEntities.push(cloneDeep(batteryEntity));
    }
    if (hasCharger) {
        mqttEntities.push(cloneDeep(chargerEntity));
    }
    if (hasOnline) {
        mqttEntities.push(cloneDeep(onlineEntity));
    }
    if (hasSleep) {
        mqttEntities.push(cloneDeep(sleepingEntity));
    }
    if (device.interfaces.includes(ScryptedInterface.VideoRecorder)) {
        mqttEntities.push({ ...recordingEntity, skipCommandTopicReset: true });
    }
    if (device.interfaces.includes(ScryptedInterface.Reboot)) {
        mqttEntities.push(rebootEntity);
    }
    if (device.interfaces.includes(ScryptedInterface.AudioVolumeControl)) {
        mqttEntities.push(audioPressureEntity);
    }
    if (device.interfaces.includes(ScryptedInterface.PanTiltZoom)) {
        const presets = Object.values(device.ptzCapabilities.presets ?? {});
        if (presets?.length) {
            mqttEntities.push({ ...ptzPresetEntity, options: presets });
        }
        mqttEntities.push(...getPtzCommandEntities(device));
    }
    for (const rule of rules) {
        const ruleEntities = getRuleMqttEntities({ rule, device, forDiscovery: true });
        for (const mqttEntity of ruleEntities) {
            if (mqttEntity.identifier === MqttEntityIdentifier.RuleActive) {
                console.info(`[getCameraMqttEntitiesForDiscovery] Rule "${rule.name}" (source=${rule.source}): RuleActive valueToDispatch=${rule.isEnabled}`);
                mqttEntities.push({ ...mqttEntity, valueToDispatch: rule.isEnabled });
            } else if (mqttEntity.identifier === MqttEntityIdentifier.RuleRunning) {
                console.info(`[getCameraMqttEntitiesForDiscovery] Rule "${rule.name}" (source=${rule.source}): RuleRunning valueToDispatch=${rule.currentlyActive}`);
                mqttEntities.push({ ...mqttEntity, valueToDispatch: rule.currentlyActive });
            } else {
                mqttEntities.push(mqttEntity);
            }
        }
    }
    mqttEntities.push(...getDetectionZoneEntities(zones));
    return mqttEntities;
};

/**
 * Initial state for camera switch entities. Used to publish state_topic with retain right after discovery
 * so HA shows correct state instead of "unknown" until the first update.
 */
export type InitialCameraState = {
    isRecording?: boolean;
    isSnapshotsEnabled?: boolean;
    isRebroadcastEnabled?: boolean;
    notificationsEnabled?: boolean;
    accessorySwitchStates?: Partial<Record<CameraAccessorySwitchKind, boolean>>;
};

/** Build initialEntityStates from InitialCameraState for publishMqttDeviceDiscovery. */
const buildCameraInitialEntityStates = (props: {
    device: ScryptedDeviceBase & ObjectDetector;
    initialCameraState?: InitialCameraState;
    accessorySwitchKinds?: CameraAccessorySwitchKind[];
    console?: Console;
}): Record<string, string> | undefined => {
    const { device, initialCameraState, accessorySwitchKinds, console } = props;
    if (!initialCameraState) {
        console?.info(`[buildCameraInitialEntityStates] No initialCameraState provided for device "${device.name}"`);
        return undefined;
    }
    const {
        batteryEntity,
        chargerEntity,
        notificationsEnabledEntity,
        onlineEntity,
        recordingEntity,
        sleepingEntity,
        snapshotsEntity,
        rebroadcastEntity,
        privacyEntity,
    } = getBasicMqttEntities();
    const hasRecording = device?.interfaces?.includes(ScryptedInterface.VideoRecorder);
    const isPrivacy =
        !initialCameraState.isRebroadcastEnabled &&
        !initialCameraState.isSnapshotsEnabled &&
        (!hasRecording || !initialCameraState.isRecording);
    const out: Record<string, string> = {};
    if (initialCameraState.notificationsEnabled !== undefined) {
        out[notificationsEnabledEntity.entity] = initialCameraState.notificationsEnabled ? PAYLOAD_ON : PAYLOAD_OFF;
    }
    if (initialCameraState.isRecording !== undefined && hasRecording) {
        out[recordingEntity.entity] = initialCameraState.isRecording ? PAYLOAD_ON : PAYLOAD_OFF;
    }
    if (initialCameraState.isSnapshotsEnabled !== undefined) {
        out[snapshotsEntity.entity] = initialCameraState.isSnapshotsEnabled ? PAYLOAD_ON : PAYLOAD_OFF;
    }
    if (initialCameraState.isRebroadcastEnabled !== undefined) {
        out[rebroadcastEntity.entity] = initialCameraState.isRebroadcastEnabled ? PAYLOAD_ON : PAYLOAD_OFF;
    }
    out[privacyEntity.entity] = isPrivacy ? PAYLOAD_ON : PAYLOAD_OFF;

    // Publish diagnostic entity initial states so HA doesn't show "Unknown"
    if (device.interfaces.includes(ScryptedInterface.Battery) && device.batteryLevel !== undefined && device.batteryLevel !== null) {
        out[batteryEntity.entity] = String(device.batteryLevel);
        console?.info(`[buildCameraInitialEntityStates] Including battery initial state: ${device.batteryLevel}`);
    }
    if (device.interfaces.includes(ScryptedInterface.Charger) && device.chargeState !== undefined && device.chargeState !== null) {
        const isCharging = device.chargeState === 'charging' || device.chargeState === 'trickle';
        out[chargerEntity.entity] = isCharging ? PAYLOAD_ON : PAYLOAD_OFF;
        console?.info(`[buildCameraInitialEntityStates] Including charger initial state: ${device.chargeState}`);
    }
    if (device.interfaces.includes(ScryptedInterface.Online) && device.online !== undefined && device.online !== null) {
        out[onlineEntity.entity] = device.online ? PAYLOAD_ON : PAYLOAD_OFF;
        console?.info(`[buildCameraInitialEntityStates] Including online initial state: ${device.online}`);
    }
    if (device.interfaces.includes(ScryptedInterface.Sleep) && device.sleeping !== undefined && device.sleeping !== null) {
        out[sleepingEntity.entity] = device.sleeping ? PAYLOAD_ON : PAYLOAD_OFF;
        console?.info(`[buildCameraInitialEntityStates] Including sleeping initial state: ${device.sleeping}`);
    }

    if (initialCameraState.accessorySwitchStates && accessorySwitchKinds?.length) {
        for (const kind of accessorySwitchKinds) {
            const state = initialCameraState.accessorySwitchStates[kind];
            if (state === undefined) continue;
            const mqttEntity = cameraAccessorySwitchEntities[kind];
            if (!mqttEntity) continue;
            out[mqttEntity.entity] = state ? PAYLOAD_ON : PAYLOAD_OFF;
        }
    }
    console?.info(`[buildCameraInitialEntityStates] Built initial states for device "${device.name}": ${JSON.stringify(Object.keys(out))}`);
    return Object.keys(out).length ? out : undefined;
};

export const setupCameraAutodiscovery = async (props: {
    mqttClient?: IHaClient,
    device: ScryptedDeviceBase & ObjectDetector,
    console: Console,
    rules: BaseRule[],
    zones: string[],
    accessorySwitchKinds?: CameraAccessorySwitchKind[],
    /** If provided, initial switch states are published right after discovery so HA shows correct state. */
    initialCameraState?: InitialCameraState,
    /** Stream destinations to expose as camera entities (included in WS entity_change payload). */
    streamDestinations?: ScryptedStreamDestination[],
}) => {
    const { device, mqttClient, rules, console, zones, accessorySwitchKinds, initialCameraState, streamDestinations } = props;
    if (!mqttClient) {
        return;
    }
    const mqttEntities = await getCameraMqttEntitiesForDiscovery({ device, rules, console, zones, accessorySwitchKinds });
    const initialEntityStates = buildCameraInitialEntityStates({ device, initialCameraState, accessorySwitchKinds, console });
    return await publishMqttDeviceDiscovery({ mqttClient, mqttEntities, device, console, initialEntityStates, streamDestinations });
};

/**
 * Rediscover a single camera on MQTT: optionally delete device from HA, clear all MQTT topics for this camera, then republish discovery.
 * If haApiUrl and haApiToken are provided, removes the device from Home Assistant first (via HA WebSocket API) so HA drops the device and entities; then clears retained topics and republishes.
 * Note: HA may log "No device components to cleanup for <id>, node_id 'None'" when removing the device; that message is from HA and is harmless.
 */
export const rediscoverCameraMqttDevice = async (props: {
    mqttClient?: IHaClient,
    device: ScryptedDeviceBase & ObjectDetector,
    console: Console,
    rules: BaseRule[],
    zones: string[],
    accessorySwitchKinds?: CameraAccessorySwitchKind[],
    haApiUrl?: string,
    haApiToken?: string,
    /** If provided, initial switch states are published right after discovery. */
    initialCameraState?: InitialCameraState,
    streamDestinations?: ScryptedStreamDestination[],
}): Promise<{ haDeviceDeleted?: boolean; haError?: string }> => {
    const { device, mqttClient, rules, console, zones, accessorySwitchKinds, haApiUrl, haApiToken, initialCameraState, streamDestinations } = props;
    const result: { haDeviceDeleted?: boolean; haError?: string } = {};

    if (mqttClient && haApiUrl?.trim() && haApiToken?.trim()) {
        const deviceIdentifier = `${idPrefix}-${device.id}`;
        const deleteResult = await deleteMqttDeviceByIdentifier(haApiUrl.trim(), haApiToken.trim(), deviceIdentifier, console);
        result.haDeviceDeleted = deleteResult.deleted;
        if (deleteResult.error) {
            result.haError = deleteResult.error;
            console.warn('HA device delete failed (continuing with topic cleanup):', deleteResult.error);
        }
    }

    if (!mqttClient) {
        return result;
    }

    const mqttEntities = await getCameraMqttEntitiesForDiscovery({ device, rules, console, zones, accessorySwitchKinds });
    await clearTopicsForEntities({ mqttClient, device, mqttEntities });
    await setupCameraAutodiscovery({ mqttClient, device, rules, console, zones, accessorySwitchKinds, initialCameraState, streamDestinations });
    return result;
};

